-- Task 21: bilingual exhibition labels for the frozen Second Batch Volume I (D2-01..D2-30).
-- Summaries preserve the catalog's cultural reading while keeping authentication claims separate.

CREATE TEMP TABLE d2_labels(
  catalog_code TEXT,
  zh_label TEXT,
  zh_text TEXT,
  eo_label TEXT,
  eo_text TEXT
) ON COMMIT DROP;


SELECT a.id,'zh',l.zh_label,l.zh_text,'published','d2-v0.1'
FROM d2_labels l JOIN cultural_assets a ON a.catalog_code=l.catalog_code
ON CONFLICT(asset_id,locale,version) DO NOTHING;

SELECT a.id,'eo',l.eo_label,l.eo_text,'published','d2-v0.1'
FROM d2_labels l JOIN cultural_assets a ON a.catalog_code=l.catalog_code
ON CONFLICT(asset_id,locale,version) DO NOTHING;
